/* Atlas verisinin kısa özeti (tools/ozet_veri.py üretir; elle düzenlenmez): tanıtım sayfası ve Kütüphane. */
window.OZET = {"regions":[{"id":"dlpfc","c":"#4f7fe0","p":null,"deep":false,"n":"Dorsolateral Prefrontal Korteks","ne":"Dorsolateral Prefrontal Cortex","s":"DLPFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Yürütücü işlevlerin merkezi: bilgiyi zihinde tutar, işler, plan yapar ve davranışı hedefe göre yönlendirir; en geç olgunlaşan, ilaç ve TMS ile en çok hedeflenen kortikal bölgelerden biridir.","de":"The hub of executive function: holds information in mind, works on it, plans and steers behavior toward goals; one of the latest-maturing cortical regions and among the most targeted by…"},{"id":"ofc","c":"#7a6ae6","p":null,"deep":false,"n":"Orbitofrontal Korteks","ne":"Orbitofrontal Cortex","s":"OFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Ödül ve cezanın değerini hesaplar; beklentiye göre davranışı esnek biçimde günceller ve sosyal uygunluğu denetler.","de":"Computes the value of rewards and punishments; flexibly updates behavior according to expectations and monitors social appropriateness."},{"id":"mofc","c":"#8676ea","p":"ofc","deep":false,"n":"Medial Orbitofrontal Korteks","ne":"Medial Orbitofrontal Cortex","s":"mOFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Ödüllerin değerini izler; beklenen sonucu temsil ederek seçimi yönlendirir.","de":"Tracks the value of rewards; guides choice by representing the expected outcome."},{"id":"lofc","c":"#7060dc","p":"ofc","deep":false,"n":"Lateral Orbitofrontal Korteks","ne":"Lateral Orbitofrontal Cortex","s":"lOFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Ceza ve olumsuz sonuçları değerlendirir; davranışın değiştirilmesi gerektiğini bildirir.","de":"Evaluates punishment and negative outcomes; signals that behaviour needs to change."},{"id":"mpfc","c":"#9b6fd6","p":null,"deep":false,"n":"Medial & Frontopolar Prefrontal Korteks","ne":"Medial & Frontopolar Prefrontal Cortex","s":"mPFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Kendilik ve başkalarının zihnini temsil eder; amigdalayı düzenleyerek korkunun sönmesini ve duygusal dengeyi sağlar.","de":"Represents the self and other minds; by regulating the amygdala it supports fear extinction and emotional balance."},{"id":"vmpfc","c":"#a47bdc","p":"mpfc","deep":false,"n":"Ventromedial Prefrontal Korteks","ne":"Ventromedial Prefrontal Cortex","s":"vmPFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Seçeneklerin öznel değerini izler; sönmüş korkunun hatırlanmasıyla amigdalayı yatıştırır.","de":"Tracks the subjective value of options; calms the amygdala through the recall of extinguished fear."},{"id":"dmpfc","c":"#9167cc","p":"mpfc","deep":false,"n":"Dorsomedial Prefrontal Korteks","ne":"Dorsomedial Prefrontal Cortex","s":"dmPFC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Başkalarının ve kendi zihinsel durumlarımızı düşünmeyi taşır; varsayılan mod ağının ön medial düğümü.","de":"Supports thinking about the mental states of others and of oneself; the anterior medial node of the default mode network."},{"id":"fpc","c":"#a98adf","p":"mpfc","deep":false,"n":"Frontal Kutup","ne":"Frontal Pole","s":"FPC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Bir hedefi askıda tutarken başka bir işe geçmeyi sağlar; yürütücü sistemin en üst basamağı olarak düşünülür.","de":"Lets one goal be held pending while switching to another task; regarded as the top level of the executive system."},{"id":"broca","c":"#3fa5d8","p":null,"deep":false,"n":"Broca Alanı (İnferior Frontal Girus)","ne":"Broca’s Area (Inferior Frontal Gyrus)","s":"Broca / IFG","g":"Frontal Lob","ge":"Frontal Lobe","d":"Konuşma üretimi, sözdizimi ve sözel çalışma belleği; sağ homoloğu yanıt ketlemede rol alır.","de":"Speech production, syntax and verbal working memory; its right-hemisphere homolog contributes to response inhibition."},{"id":"ifg44","c":"#4fb1e0","p":"broca","deep":false,"n":"Pars Opercularis (Alan 44)","ne":"Pars Opercularis (Area 44)","s":"IFG 44","g":"Frontal Lob","ge":"Frontal Lobe","d":"Solda Broca bölgesinin arka parçası; sağ yanı yanıt ketleme araştırmalarının başlıca hedefi.","de":"The posterior part of Broca's region on the left; its right counterpart is a main target of response-inhibition research."},{"id":"ifg45","c":"#3598cc","p":"broca","deep":false,"n":"Pars Triangularis (Alan 45)","ne":"Pars Triangularis (Area 45)","s":"IFG 45","g":"Frontal Lob","ge":"Frontal Lobe","d":"Bellekten gelen seçenekler arasından doğru olanı seçmeye yardım eder; solda Broca bölgesinin ön parçası.","de":"Helps select the right item among options retrieved from memory; the anterior part of Broca's region on the left."},{"id":"fop","c":"#61b9e4","p":"broca","deep":false,"n":"Frontal Operkulum","ne":"Frontal Operculum","s":"FOP","g":"Frontal Lob","ge":"Frontal Lobe","d":"İnsulayı örten frontal duvar; görev kontrolü ve tat işlemeyle ilişkilidir.","de":"The frontal wall covering the insula; associated with task control and taste processing."},{"id":"premotor","c":"#4cb3b0","p":null,"deep":false,"n":"Premotor Korteks & SMA","ne":"Premotor Cortex & SMA","s":"PMC / SMA","g":"Frontal Lob","ge":"Frontal Lobe","d":"Hareketi planlar ve sıraya koyar; içsel olarak başlatılan eylemleri, iki elin uyumunu ve göz hareketlerini yönetir.","de":"Plans and sequences movement; manages internally initiated actions, bimanual coordination and eye movements."},{"id":"sma","c":"#5cc0bd","p":"premotor","deep":false,"n":"Ek Motor Alan ve Pre-SMA","ne":"Supplementary Motor Area and Pre-SMA","s":"SMA / pre-SMA","g":"Frontal Lob","ge":"Frontal Lobe","d":"Bilişi eyleme bağlar; uyarılınca hareket etme isteği doğurabilir.","de":"Links cognition to action; stimulation can evoke an urge to move."},{"id":"lpm","c":"#3fa5a2","p":"premotor","deep":false,"n":"Lateral Premotor Korteks","ne":"Lateral Premotor Cortex","s":"Lateral PMC","g":"Frontal Lob","ge":"Frontal Lobe","d":"Hareketi planlar ve seçer; dorsal ve ventral premotor alanlarla frontal göz alanını içerir.","de":"Plans and selects movement; includes dorsal and ventral premotor areas and the frontal eye field."},{"id":"motor","c":"#2f9a8a","p":null,"deep":false,"n":"Primer Motor Korteks","ne":"Primary Motor Cortex","s":"M1","g":"Frontal Lob","ge":"Frontal Lobe","d":"İstemli hareketin yürütücüsü: kortikospinal yolun ana kaynağıdır, vücudun karşı yarısını kontrol eder.","de":"Executor of voluntary movement: the main source of the corticospinal tract, controlling the opposite half of the body."},{"id":"somato","c":"#e9a23b","p":null,"deep":false,"n":"Primer Somatosensoriyel Korteks","ne":"Primary Somatosensory Cortex","s":"S1","g":"Parietal Lob","ge":"Parietal Lobe","d":"Dokunma, basınç, ağrı, ısı ve vücut pozisyonu bilgisini haritalayarak bedeni algılatır.","de":"Makes the body felt by mapping touch, pressure, pain, temperature and body position."},{"id":"spl","c":"#c9b03a","p":null,"deep":false,"n":"Superior Parietal Lobül","ne":"Superior Parietal Lobule","s":"SPL / IPS","g":"Parietal Lob","ge":"Parietal Lobe","d":"Görme ile hareketi birleştirir: nesnenin nerede olduğunu hesaplar, uzanma ve kavramayı yönlendirir, sayı hissine katkı verir.","de":"Joins vision with movement: computes where an object is, guides reaching and grasping, and contributes to number sense."},{"id":"ipl","c":"#d98a2b","p":null,"deep":false,"n":"İnferior Parietal Lobül","ne":"Inferior Parietal Lobule","s":"IPL","g":"Parietal Lob","ge":"Parietal Lobe","d":"Okuma, hesaplama ve praksisin (sol); dikkatin yeniden yönlenmesi ve başkasının bakış açısını almanın (sağ) bölgesi.","de":"The region of reading, calculation and praxis (left), and of reorienting attention and taking another’s perspective (right)."},{"id":"tpj","c":"#7b5ea7","p":null,"deep":false,"n":"Temporoparietal Bileşke","ne":"Temporoparietal Junction","s":"TPJ","g":"Parietal Lob","ge":"Parietal Lobe","d":"Kendini başkasından ayırma, başkasının inancını temsil etme ve dikkati beklenmedik uyaranlara çevirme bölgesi; sağ TPJ zihin kuramının kortikal merkezlerinden biridir.","de":"The region for telling self from other, representing another’s beliefs and turning attention to unexpected stimuli; the right TPJ is one of the cortical hubs of theory of mind."},{"id":"stg","c":"#e0703c","p":null,"deep":false,"n":"Superior Temporal Girus & Wernicke","ne":"Superior Temporal Gyrus & Wernicke","s":"STG / STS","g":"Temporal Lob","ge":"Temporal Lobe","d":"Duyduğumuzu işler ve anlamlandırır; sesler, konuşma, prozodi ve sosyal hareket algısı burada birleşir.","de":"Processes what we hear and makes sense of it; sounds, speech, prosody and the perception of social motion come together here."},{"id":"audstg","c":"#e67d4a","p":"stg","deep":false,"n":"Üst Temporal Girus ve İşitsel Korteks","ne":"Superior Temporal Gyrus and Auditory Cortex","s":"STG / A1","g":"Temporal Lob","ge":"Temporal Lobe","d":"Sesin ve konuşmanın kortekste ilk işlendiği yer: Heschl girusundaki birincil işitsel korteks ve çevresi.","de":"Where sound and speech are first processed in the cortex: primary auditory cortex on Heschl's gyrus and its surroundings."},{"id":"sts","c":"#d96a34","p":"stg","deep":false,"n":"Üst Temporal Sulkus","ne":"Superior Temporal Sulcus","s":"STS","g":"Temporal Lob","ge":"Temporal Lobe","d":"Bakış, yüz hareketi, ses ve beden hareketi gibi sosyal ipuçlarının buluştuğu oluk.","de":"The sulcus where social cues such as gaze, facial movement, voice and body movement converge."},{"id":"tpole","c":"#d9613c","p":"stg","deep":false,"n":"Temporal Kutup","ne":"Temporal Pole","s":"TP","g":"Temporal Lob","ge":"Temporal Lobe","d":"Temporal lobun ön ucu; işlenmiş algıyı duygusal yanıtla ve kavram bilgisiyle bağladığı düşünülür.","de":"The front end of the temporal lobe; thought to bind processed perception to emotional response and conceptual knowledge."},{"id":"itg","c":"#d4573f","p":null,"deep":false,"n":"İnferior Temporal & Fusiform Korteks","ne":"Inferior Temporal & Fusiform Cortex","s":"ITG / FG","g":"Temporal Lob","ge":"Temporal Lobe","d":"Gördüğümüzün \"ne\" olduğunu söyler: yüz, nesne ve yazılı sözcük tanıma; kavram bilgisinin deposu.","de":"Tells us “what” we see: recognition of faces, objects and written words; a store of conceptual knowledge."},{"id":"fusiform","c":"#de6a53","p":"itg","deep":false,"n":"Fusiform Girus","ne":"Fusiform Gyrus","s":"FG","g":"Temporal Lob","ge":"Temporal Lobe","d":"Yüzleri ve nesne biçimlerini tanımada görev alır; yüz alanı burada bulunur.","de":"Takes part in recognizing faces and object forms; home of the face area."},{"id":"ento","c":"#c64a33","p":"itg","deep":false,"n":"Entorinal ve Peririnal Korteks","ne":"Entorhinal and Perirhinal Cortex","s":"EC / PRC","g":"Temporal Lob","ge":"Temporal Lobe","d":"Parahipokampal korteksten aldığı girdiyi hipokampusa iletir; konum ve tanıdıklık bilgisi taşır, Alzheimer patolojisinin erken durağıdır.","de":"Passes input from parahippocampal cortex to the hippocampus; carries position and familiarity information, and is an early site of Alzheimer pathology."},{"id":"phg","c":"#d9604a","p":"itg","deep":false,"n":"Parahipokampal Korteks","ne":"Parahippocampal Cortex","s":"PHC","g":"Temporal Lob","ge":"Temporal Lobe","d":"Sahne ve bağlam bilgisini belleğe bağlar; parahipokampal yer alanını içerir.","de":"Links scene and context information to memory; includes the parahippocampal place area."},{"id":"mitg","c":"#cf523a","p":"itg","deep":false,"n":"Orta ve Alt Temporal Girus","ne":"Middle and Inferior Temporal Gyri","s":"MTG / ITG","g":"Temporal Lob","ge":"Temporal Lobe","d":"Kavram ve sözcük anlamının dağıtık ağındaki temporal düğüm.","de":"The temporal node of the distributed network for concepts and word meaning."},{"id":"occipital","c":"#5aa85a","p":null,"deep":false,"n":"Oksipital Lob — Görsel Korteks","ne":"Occipital Lobe — Visual Cortex","s":"V1–V5","g":"Oksipital Lob","ge":"Occipital Lobe","d":"Görsel bilginin ilk işlendiği yer: kenar, yön, renk, hareket ve derinliği çözümleyip dorsal ve ventral akımlara dağıtır.","de":"Where visual information is first processed: it analyzes edges, orientation, color, motion and depth and distributes them to the dorsal and ventral streams."},{"id":"acc","c":"#e0646f","p":null,"deep":false,"n":"Anterior Singulat Korteks","ne":"Anterior Cingulate Cortex","s":"ACC","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Hata ve çatışmayı fark eder, çabayı ayarlar; duygu, ağrı ve dikkat arasında köprü kurar.","de":"Detects errors and conflict and adjusts effort; bridges emotion, pain and attention."},{"id":"sgacc","c":"#e8737c","p":"acc","deep":false,"n":"Subgenual Ön Singulat","ne":"Subgenual Anterior Cingulate","s":"sgACC","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Korpus kallozum dizinin altındaki singulat: duygu ve otonom düzenlemenin düğümü, depresyon araştırmalarının başlıca hedefi.","de":"The cingulate below the genu of the corpus callosum: a node for emotional and autonomic regulation and a main target of depression research."},{"id":"pgacc","c":"#dc5a66","p":"acc","deep":false,"n":"Pregenual Ön Singulat","ne":"Pregenual Anterior Cingulate","s":"pgACC","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Dizin önündeki singulat: duygusal çatışmayı çözerken amigdalayı yukarıdan düzenler.","de":"The cingulate in front of the genu: regulates the amygdala from above while resolving emotional conflict."},{"id":"dacc","c":"#d6505e","p":"acc","deep":false,"n":"Dorsal Ön Singulat ve Ön Orta Singulat","ne":"Dorsal Anterior and Anterior Midcingulate Cortex","s":"dACC","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Olumsuz duygu, ağrı ve bilişsel kontrolün buluştuğu yer; salience ağının medial düğümü.","de":"Where negative affect, pain and cognitive control converge; the medial node of the salience network."},{"id":"insula","c":"#d9539a","p":null,"deep":false,"n":"İnsula","ne":"Insula","s":"İnsula","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Bedenin içini hisseder: kalp atışı, açlık, tiksinme ve ağrıyı öznel duyguya dönüştürür; belirgin olana dikkati çevirir.","de":"Feels the inside of the body: turns heartbeat, hunger, disgust and pain into subjective feeling, and turns attention to what is salient."},{"id":"aic","c":"#df62a4","p":"insula","deep":false,"n":"Ön İnsula","ne":"Anterior Insula","s":"aINS","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Bedenden gelen sinyali duyguya ve farkındalığa çevirir; önemli olanı işaretleyerek ağlar arasında geçişi başlatır.","de":"Turns bodily signals into feeling and awareness; marks what matters and initiates switching between networks."},{"id":"pic","c":"#cf4890","p":"insula","deep":false,"n":"Arka İnsula","ne":"Posterior Insula","s":"pINS","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Bedenin iç durumunun birincil haritası: ısı, ağrı ve iç organ duyusu buraya ulaşır.","de":"The primary map of the body's internal state: temperature, pain and visceral sensation arrive here."},{"id":"pcc","c":"#c76ab0","p":null,"deep":false,"n":"Posterior Singulat & Prekuneus","ne":"Posterior Cingulate & Precuneus","s":"PCC / Prekuneus","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Varsayılan mod ağının merkezi: iç odaklı düşünce, otobiyografik bellek ve kendilik deneyimi burada toplanır.","de":"The hub of the default mode network: inward-directed thought, autobiographical memory and the experience of self converge here."},{"id":"pcing","c":"#bf5ea7","p":"pcc","deep":false,"n":"Posterior Singulat Korteks","ne":"Posterior Cingulate Cortex","s":"PCC","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Varsayılan mod ağının arka düğümü; yoğun bağlantılı ve metabolik olarak etkindir, bilişsel rolü tartışmalıdır.","de":"The posterior node of the default mode network; densely connected and metabolically active, with a debated cognitive role."},{"id":"prek","c":"#cf78ba","p":"pcc","deep":false,"n":"Prekuneus","ne":"Precuneus","s":"Prekuneus","g":"Limbik Korteks & İnsula","ge":"Limbic Cortex & Insula","d":"Medial parietal yüzde; görsel-mekânsal imgelem, anı geri çağırma ve kendilikle ilgili işlemlerde rol alır.","de":"On the medial parietal surface; involved in visuospatial imagery, memory retrieval and self-related processing."},{"id":"hippocampus","c":"#f08a5d","p":null,"deep":true,"n":"Hipokampus","ne":"Hippocampus","s":"HC","g":"Limbik Yapılar","ge":"Limbic Structures","d":"Yeni anıları kodlar ve pekiştirir; mekânı ve bağlamı haritalar, stres yanıtını frenler.","de":"Encodes and consolidates new memories; maps space and context, and brakes the stress response."},{"id":"amygdala","c":"#e8505b","p":null,"deep":true,"n":"Amigdala","ne":"Amygdala","s":"AMY","g":"Limbik Yapılar","ge":"Limbic Structures","d":"Duygusal önem (salience) dedektörü: bir uyaranın \"benim için önemli mi, tehlikeli mi, değerli mi\" sorusunu hızla yanıtlar, bu ilişkiyi öğrenir ve bedeni…","de":"A detector of emotional salience: quickly answers “does this matter to me — is it dangerous, is it valuable?”, learns that association and prepares the body…"},{"id":"bnst","c":"#f0849b","p":null,"deep":true,"n":"Stria Terminalis Yatak Çekirdeği","ne":"Bed Nucleus of the Stria Terminalis","s":"BNST","g":"Limbik Yapılar","ge":"Limbic Structures","d":"Genişletilmiş amigdalanın parçası: belirsiz ve uzak tehditlere karşı süreğen kaygıyı yürütür, stres eksenini ayarlar.","de":"Part of the extended amygdala: drives sustained anxiety in the face of uncertain and distant threats, and tunes the stress axis."},{"id":"nbm","c":"#22c7d6","p":null,"deep":true,"n":"Meynert Bazal Çekirdeği","ne":"Nucleus Basalis of Meynert","s":"NBM","g":"Limbik Yapılar","ge":"Limbic Structures","d":"Neokorteksin başlıca asetilkolin kaynağı: dikkati, uyarana yönelmeyi ve öğrenmeyi destekler; Alzheimer ve Lewy cisimcikli demanslarda erken yıkılır.","de":"The main source of acetylcholine for the neocortex: supports attention, orienting to stimuli and learning; degenerates early in Alzheimer's disease and Lewy body dementias."},{"id":"dbb","c":"#7fe3a8","p":null,"deep":true,"n":"Broca'nın Diyagonal Bandı","ne":"Diagonal Band of Broca","s":"DBB","g":"Limbik Yapılar","ge":"Limbic Structures","d":"Medial septumla birlikte hipokampusun asetilkolin ve GABA kaynağı: teta ritmini ve yeni anıların kaydını düzenleyen bazal önbeyin çekirdeği.","de":"With the medial septum, the source of acetylcholine and GABA for the hippocampus: a basal forebrain nucleus that regulates the theta rhythm and the encoding of new memories."},{"id":"caudate","c":"#4aa3df","p":null,"deep":true,"n":"Kaudat Nükleus","ne":"Caudate Nucleus","s":"CN","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Prefrontal korteksin striatal ortağı: hedefe yönelik davranışı, geri bildirimle öğrenmeyi ve bilişsel esnekliği destekler.","de":"The striatal partner of the prefrontal cortex: supports goal-directed behavior, learning from feedback and cognitive flexibility."},{"id":"putamen","c":"#3c7fc7","p":null,"deep":true,"n":"Putamen","ne":"Putamen","s":"PUT","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Motor döngünün giriş kapısı: hareketin başlatılması, otomatikleşen alışkanlıklar ve motor sekans öğrenmesi.","de":"The entry gate of the motor loop: initiation of movement, habits that become automatic and motor sequence learning."},{"id":"gp","c":"#6f8fd8","p":null,"deep":true,"n":"Globus Pallidus","ne":"Globus Pallidus","s":"GPe / GPi","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Bazal ganglionların çıkış freni: talamusu tonik olarak baskılar, istenen hareketi serbest bırakır, istenmeyeni durdurur.","de":"The output brake of the basal ganglia: tonically suppresses the thalamus, releases the wanted movement and stops the unwanted one."},{"id":"gpe","c":"#8fa9ea","p":"gp","deep":true,"n":"Globus Pallidus Dış Segment","ne":"Globus Pallidus, External Segment","s":"GPe","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Dolaylı yolun ara istasyonu: subtalamik çekirdeği frenleyerek istenmeyen hareketlerin baskılanmasını ayarlar.","de":"The relay station of the indirect pathway: tunes the suppression of unwanted movements by braking the subthalamic nucleus."},{"id":"gpi","c":"#3f63c4","p":"gp","deep":true,"n":"Globus Pallidus İç Segment","ne":"Globus Pallidus, Internal Segment","s":"GPi","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Bazal ganglionların ana çıkış çekirdeği: talamusu frenler; distoni ve dirençli Tourette'te derin beyin stimülasyonu hedefi.","de":"The main output nucleus of the basal ganglia: brakes the thalamus; a deep brain stimulation target in dystonia and refractory Tourette syndrome."},{"id":"stn","c":"#2e9e6a","p":null,"deep":true,"n":"Subtalamik Çekirdek","ne":"Subthalamic Nucleus","s":"STN","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Bazal ganglionların \"dur\" düğmesi: hiperdirekt yolla korteksten hızlı sinyal alır ve hareketleri ve kararları bir an için frenler.","de":"The “stop” button of the basal ganglia: receives fast signals from the cortex through the hyperdirect pathway and briefly brakes movements and decisions."},{"id":"sn","c":"#4a4f9e","p":null,"deep":true,"n":"Substantia Nigra","ne":"Substantia Nigra","s":"SN","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Orta beyindeki \"kara cisim\": dopaminle hareketi ve alışkanlık öğrenmesini besleyen kompakta ile bazal ganglionların çıkışını taşıyan retikülata bölümlerinden oluşur.","de":"The midbrain’s “black substance”: made of the compacta, which feeds movement and habit learning with dopamine, and the reticulata, which carries the output of the basal ganglia."},{"id":"snc","c":"#2f3a8f","p":"sn","deep":true,"n":"Substantia Nigra Pars Kompakta","ne":"Substantia Nigra Pars Compacta","s":"SNc","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Nigrostriatal dopamin yolunun kaynağı: dorsal striatumu besleyerek hareketi ve alışkanlık öğrenmesini destekler.","de":"Source of the nigrostriatal dopamine pathway: supports movement and habit learning by feeding the dorsal striatum."},{"id":"snr","c":"#7d86d6","p":"sn","deep":true,"n":"Substantia Nigra Pars Retikülata","ne":"Substantia Nigra Pars Reticulata","s":"SNr","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"GPi ile birlikte bazal ganglionların iki çıkış çekirdeğinden biri: talamusu ve superior kollikulusu frenleyen GABAerjik nöronlar.","de":"One of the two output nuclei of the basal ganglia, together with the GPi: GABAergic neurons that brake the thalamus and superior colliculus."},{"id":"nacc","c":"#f2b134","p":null,"deep":true,"n":"Nükleus Akumbens","ne":"Nucleus Accumbens","s":"NAcc / VS","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Ödülün motivasyona dönüştüğü yer: \"istemek\", yaklaşma davranışı ve pekiştirmeyle öğrenme.","de":"Where reward becomes motivation: “wanting”, approach behavior and reinforcement learning."},{"id":"vp","c":"#a3349a","p":null,"deep":true,"n":"Ventral Pallidum","ne":"Ventral Pallidum","s":"VP","g":"Bazal Ganglionlar","ge":"Basal Ganglia","d":"Ödülün \"beğenilme\" ve motivasyon çıkışı: nükleus akumbensten gelen sinyali talamus ve beyin sapına aktarır; hedonik sıcak noktalar içerir.","de":"The output for reward “liking” and motivation: relays signals from the nucleus accumbens to the thalamus and brainstem; contains hedonic hot spots."},{"id":"thalamus","c":"#8a7ff0","p":null,"deep":true,"n":"Talamus","ne":"Thalamus","s":"TH","g":"Diensefalon","ge":"Diencephalon","d":"Kortekse açılan kapı: koku dışındaki tüm duyuları süzer ve aktarır; uyanıklığı, dikkati ve motor döngüleri düzenler.","de":"The gateway to the cortex: filters and relays every sense except smell; regulates wakefulness, attention and the motor loops."},{"id":"th_ant","c":"#4fae7c","p":"thalamus","deep":true,"n":"Anterior Çekirdek Grubu","ne":"Anterior Nuclear Group","s":"AN","g":"Diensefalon","ge":"Diencephalon","d":"Papez devresinin talamik istasyonu: mamiller cisimden gelen bilgiyi singulat kortekse aktararak epizodik belleği ve yön bulmayı destekler.","de":"The thalamic station of the Papez circuit: relays information from the mammillary body to the cingulate cortex, supporting episodic memory and navigation."},{"id":"th_md","c":"#e0b23a","p":"thalamus","deep":true,"n":"Mediodorsal Çekirdek","ne":"Mediodorsal Nucleus","s":"MD","g":"Diensefalon","ge":"Diencephalon","d":"Prefrontal korteksin talamik ortağı: çalışma belleği, karar verme ve ödül öğrenmesini prefrontal devrelerle birlikte yürütür.","de":"The thalamic partner of the prefrontal cortex: carries out working memory, decision-making and reward learning together with prefrontal circuits."},{"id":"th_va","c":"#e0646f","p":"thalamus","deep":true,"n":"Ventral Anterior Çekirdek","ne":"Ventral Anterior Nucleus","s":"VA","g":"Diensefalon","ge":"Diencephalon","d":"Bazal ganglion çıkışını premotor ve prefrontal kortekse ileten motor planlama istasyonu.","de":"A motor planning station that relays basal ganglia output to premotor and prefrontal cortex."},{"id":"th_vld","c":"#d98a2b","p":"thalamus","deep":true,"n":"Ventral Lateral Grup (Dorsal Bölüm)","ne":"Ventral Lateral Group (Dorsal Part)","s":"VLd","g":"Diensefalon","ge":"Diencephalon","d":"Ventral lateral bölgenin dorsal kısmı: serebellum ve bazal ganglion girdilerini motor kortekse aktaran röle çekirdeklerinin bulunduğu alan.","de":"The dorsal part of the ventral lateral region: the area holding the relay nuclei that pass cerebellar and basal ganglia input to motor cortex."},{"id":"th_vlv","c":"#c94f7c","p":"thalamus","deep":true,"n":"Ventral Lateral Grup (Ventral Bölüm)","ne":"Ventral Lateral Group (Ventral Part)","s":"VLv","g":"Diensefalon","ge":"Diencephalon","d":"Ventral lateral bölgenin ventral kısmı: motor ve duyusal röle çekirdeklerine komşu, korteksle karşılıklı bağlantılı alan.","de":"The ventral part of the ventral lateral region: an area next to the motor and sensory relay nuclei, reciprocally connected with the cortex."},{"id":"th_cl","c":"#4aa3df","p":"thalamus","deep":true,"n":"Santral Lateral – Lateral Posterior – Medial Pulvinar","ne":"Central Lateral – Lateral Posterior – Medial Pulvinar","s":"CL-LP-MPu","g":"Diensefalon","ge":"Diencephalon","d":"Uyanıklıkla ilişkili intralaminar santral lateral çekirdeği ve asosiyasyon kortekslerine bağlı lateral posterior ile medial pulvinarı içeren grup.","de":"A group containing the arousal-related intralaminar central lateral nucleus and the lateral posterior and medial pulvinar nuclei linked to association cortices."},{"id":"th_pul","c":"#6a5acd","p":"thalamus","deep":true,"n":"Pulvinar","ne":"Pulvinar","s":"Pul","g":"Diensefalon","ge":"Diencephalon","d":"Talamusun en büyük çekirdeği: görsel dikkati, belirginliği ve korteks alanları arasındaki iletişimi düzenler.","de":"The largest thalamic nucleus: regulates visual attention, salience and communication between cortical areas."},{"id":"hypothalamus","c":"#b06fd8","p":null,"deep":true,"n":"Hipotalamus & Hipofiz","ne":"Hypothalamus & Pituitary","s":"HT","g":"Diensefalon","ge":"Diencephalon","d":"İç dengenin yöneticisi: ısı, açlık, uyku, stres ve puberteyi hormonlar ve otonom sinir sistemiyle düzenler.","de":"The manager of internal balance: regulates temperature, hunger, sleep, stress and puberty through hormones and the autonomic nervous system."},{"id":"hy_mpo","c":"#f27fb8","p":"hypothalamus","deep":true,"n":"Medial Preoptik Çekirdek","ne":"Medial Preoptic Nucleus","s":"MPO","g":"Diensefalon","ge":"Diencephalon","d":"Hipotalamusun en ön ucundaki çekirdek: ebeveyn bakımı, cinsel davranış ve ısı düzenlemesinde rol alır.","de":"The nucleus at the front end of the hypothalamus: involved in parental care, sexual behaviour and temperature regulation."},{"id":"hy_scn","c":"#f2d94e","p":"hypothalamus","deep":true,"n":"Suprakiazmatik Çekirdek","ne":"Suprachiasmatic Nucleus","s":"SCN","g":"Diensefalon","ge":"Diencephalon","d":"Beynin ana sirkadiyen saati: retinadan gelen ışık bilgisiyle uyku, beslenme, hormon ve beden ısısı ritimlerini günün saatine eşler.","de":"The brain's master circadian clock: uses light information from the retina to align sleep, feeding, hormone and body temperature rhythms with the time of day."},{"id":"hy_so","c":"#48b6e8","p":"hypothalamus","deep":true,"n":"Supraoptik Çekirdek","ne":"Supraoptic Nucleus","s":"SON","g":"Diensefalon","ge":"Diencephalon","d":"Optik yolun üstündeki iri hücreli çekirdek: vazopressin ve oksitosini doğrudan arka hipofize taşıyarak su dengesini korur.","de":"The large-cell nucleus above the optic tract: carries vasopressin and oxytocin directly to the posterior pituitary and maintains water balance."},{"id":"hy_aha","c":"#f39c4a","p":"hypothalamus","deep":true,"n":"Anterior Hipotalamik Alan","ne":"Anterior Hypothalamic Area","s":"AHA","g":"Diensefalon","ge":"Diencephalon","d":"Preoptik alanla tuber bölgesi arasındaki alan: ısı düzenlemede ve savunma ya da saldırı davranışlarında rol alır.","de":"The area between the preoptic area and the tuberal region: involved in temperature regulation and in defensive or aggressive behaviour."},{"id":"hy_pvn","c":"#e0405a","p":"hypothalamus","deep":true,"n":"Paraventriküler Çekirdek","ne":"Paraventricular Nucleus","s":"PVN","g":"Diensefalon","ge":"Diencephalon","d":"Stres ekseninin komuta noktası: CRH ile HPA eksenini başlatır; oksitosin ve vazopressinle bağlanma ve su dengesine, beyin sapına inen lifleriyle otonom yanıtlara katılır.","de":"The command post of the stress axis: starts the HPA axis with CRH; with oxytocin and vasopressin it contributes to bonding and water balance, and through fibres descending to the brainstem…"},{"id":"hy_dmh","c":"#5b8def","p":"hypothalamus","deep":true,"n":"Dorsomedial Çekirdek","ne":"Dorsomedial Nucleus","s":"DMH","g":"Diensefalon","ge":"Diencephalon","d":"SCN'den gelen saat bilgisini uyku, beslenme ve kortizol ritimlerine çeviren ara istasyon; strese bağlı ısı ve kalp hızı artışını da yönetir.","de":"A relay that turns clock information from the SCN into rhythms of sleep, feeding and cortisol; also drives the rise in temperature and heart rate under stress."},{"id":"hy_vmh","c":"#9b5de5","p":"hypothalamus","deep":true,"n":"Ventromedial Çekirdek","ne":"Ventromedial Nucleus","s":"VMH","g":"Diensefalon","ge":"Diencephalon","d":"Tuber bölgesinin büyük çekirdeği: savunma ve saldırı yanıtlarını, tokluk ve glukoz dengesini düzenler.","de":"The large nucleus of the tuberal region: regulates defensive and aggressive responses, satiety and glucose balance."},{"id":"hy_arc","c":"#3ccf8e","p":"hypothalamus","deep":true,"n":"Arkuat Çekirdek","ne":"Arcuate Nucleus","s":"ARC","g":"Diensefalon","ge":"Diencephalon","d":"Hipotalamusun tabanındaki iştah ve hormon merkezi: açlık ve tokluk nöronlarını, prolaktini frenleyen dopamin nöronlarını ve puberteyi başlatan kisspeptin nöronlarını barındırır.","de":"The appetite and hormone centre at the base of the hypothalamus: houses the hunger and satiety neurons, the dopamine neurons that restrain prolactin and the kisspeptin neurons that start…"},{"id":"hy_lh","c":"#d26cf0","p":"hypothalamus","deep":true,"n":"Lateral Hipotalamus","ne":"Lateral Hypothalamus","s":"LH","g":"Diensefalon","ge":"Diencephalon","d":"Oreksin ve MCH nöronlarının yuvası: uyanıklığı, beslenmeyi ve ödül arayışını besleyen, medial önbeyin demetinin geçtiği geniş alan.","de":"Home of the orexin and MCH neurons: a broad area, crossed by the medial forebrain bundle, that feeds wakefulness, feeding and reward seeking."},{"id":"hy_tm","c":"#b8e04a","p":"hypothalamus","deep":true,"n":"Tuberomamiller Çekirdek","ne":"Tuberomammillary Nucleus","s":"TMN","g":"Diensefalon","ge":"Diencephalon","d":"Beynin tek histamin kaynağı: uyanıklığı destekler; birçok psikiyatrik ilacın uyku hali ve iştah artışı yan etkisinin hedefidir.","de":"The brain's only source of histamine: supports wakefulness; the target behind the sleepiness and appetite gain caused by many psychiatric drugs."},{"id":"hy_ph","c":"#6ec6c0","p":"hypothalamus","deep":true,"n":"Posterior Hipotalamik Çekirdek","ne":"Posterior Hypothalamic Nucleus","s":"PH","g":"Diensefalon","ge":"Diencephalon","d":"Mamiller cisimlerin üstündeki çekirdek: uyarılma ve sempatik yanıtlarda rol alır; dirençli saldırganlıkta ve küme baş ağrısında deneysel derin beyin uyarımı hedefi.","de":"The nucleus above the mammillary bodies: involved in arousal and sympathetic responses; an experimental deep brain stimulation target in refractory aggression and cluster headache."},{"id":"hy_mm","c":"#ffb3a7","p":"hypothalamus","deep":true,"n":"Mamiller Cisim","ne":"Mammillary Body","s":"MB","g":"Diensefalon","ge":"Diencephalon","d":"Hipotalamusun arka ucundaki yuvarlak çıkıntılar: forniksle hipokampustan bilgi alır, mamillotalamik yolla anterior talamusa iletir; Papez devresinin bellek istasyonu.","de":"The round eminences at the back end of the hypothalamus: receive information from the hippocampus through the fornix and pass it to the anterior thalamus through the mammillothalamic tract."},{"id":"pit","c":"#bd80e0","p":"hypothalamus","deep":true,"n":"Hipofiz","ne":"Pituitary Gland","s":"Hipofiz","g":"Diensefalon","ge":"Diencephalon","d":"Hipotalamusun komutunu kana çeviren bez: ACTH, prolaktin, büyüme hormonu ve arka lobdan oksitosin ile vazopressin.","de":"The gland that turns hypothalamic commands into blood signals: ACTH, prolactin, growth hormone and, from the posterior lobe, oxytocin and vasopressin."},{"id":"hb","c":"#e0a03a","p":null,"deep":true,"n":"Habenula","ne":"Habenula","s":"Hb","g":"Diensefalon","ge":"Diencephalon","d":"Hayal kırıklığı ve kaçınmanın sinyali: beklenen ödül gelmeyince etkinleşir, dopamin ve serotonin nöronlarını frenler; depresyonda aşırı etkin olduğu düşünülür.","de":"The signal of disappointment and avoidance: activates when an expected reward does not come and brakes dopamine and serotonin neurons; thought to be overactive in depression."},{"id":"cc","c":"#d7dde8","p":null,"deep":true,"n":"Korpus Kallozum","ne":"Corpus Callosum","s":"CC","g":"Komissürler","ge":"Commissures","d":"İki hemisferi birbirine bağlayan en büyük ak madde köprüsü; duyusal, motor ve bilişsel bilgiyi paylaştırır.","de":"The largest white matter bridge joining the two hemispheres; shares sensory, motor and cognitive information between them."},{"id":"midbrain","c":"#c9a07a","p":null,"deep":true,"n":"Mezensefalon (Orta Beyin)","ne":"Mesencephalon (Midbrain)","s":"Orta beyin","g":"Beyin Sapı","ge":"Brainstem","d":"Dopaminin kaynağı: hareket (substantia nigra) ve ödül–motivasyon (VTA); savunma, ağrı ve göz refleksleri.","de":"The source of dopamine: movement (substantia nigra) and reward–motivation (VTA); defense, pain and eye reflexes."},{"id":"pag","c":"#ec7a3c","p":null,"deep":true,"n":"Periakuaduktal Gri Madde","ne":"Periaqueductal Gray","s":"PAG","g":"Beyin Sapı","ge":"Brainstem","d":"Orta beyinde akuadüktü saran gri madde: savunma (savaş, kaç, don), ağrının bastırılması ve duygusal seslenmenin ortak çıkış istasyonu.","de":"Gray matter surrounding the aqueduct in the midbrain: the shared output station for defense (fight, flight, freeze), pain suppression and emotional vocalization."},{"id":"vta","c":"#f5c542","p":null,"deep":true,"n":"Ventral Tegmental Alan","ne":"Ventral Tegmental Area","s":"VTA","g":"Beyin Sapı","ge":"Brainstem","d":"Mezolimbik ve mezokortikal dopaminin kaynağı: motivasyonun, ödül beklentisinin ve öğrenmenin sinyalini üretir.","de":"Source of mesolimbic and mesocortical dopamine: produces the signal for motivation, reward expectation and learning."},{"id":"rn","c":"#e0263f","p":null,"deep":true,"n":"Kırmızı Çekirdek","ne":"Red Nucleus","s":"RN","g":"Beyin Sapı","ge":"Brainstem","d":"Orta beyinde serebellum ile motor sistem arasındaki istasyon: hareketin koordinasyonuna ve motor öğrenmeye katkıda bulunur.","de":"A midbrain station between the cerebellum and the motor system: contributes to movement coordination and motor learning."},{"id":"rf","c":"#1f8a78","p":null,"deep":true,"n":"Retiküler Formasyon (Mezensefalik ve Pontin)","ne":"Reticular Formation (Mesencephalic and Pontine)","s":"mRt / PnO","g":"Beyin Sapı","ge":"Brainstem","d":"Beyin sapının ortasındaki ağ benzeri çekirdek alanı: kortekse yükselen uyanıklık sinyalini taşır (ARAS), bilinç düzeyini ve kas tonusunu ayarlar.","de":"The net-like core of the brainstem: carries the ascending wakefulness signal to the cortex (ARAS), and sets the level of consciousness and muscle tone."},{"id":"ppn","c":"#8e5bd6","p":null,"deep":true,"n":"Pedinkülopontin ve Laterodorsal Tegmental Çekirdekler","ne":"Pedunculopontine and Laterodorsal Tegmental Nuclei","s":"PPN / LDT","g":"Beyin Sapı","ge":"Brainstem","d":"Beyin sapının asetilkolin kaynağı: uyanıklığı ve REM uykusunu açar, dikkati ve ödüle yönelimi destekler; PPN yürüme ve postürde de rol alır.","de":"The brainstem’s source of acetylcholine: switches on wakefulness and REM sleep, supports attention and orientation to reward; the PPN also contributes to gait and posture."},{"id":"raphe","c":"#7cb342","p":null,"deep":true,"n":"Rafe Çekirdekleri (Dorsal ve Median)","ne":"Raphe Nuclei (Dorsal and Median)","s":"DR / MnR","g":"Beyin Sapı","ge":"Brainstem","d":"Ön beyne giden serotoninin ana kaynağı: duygudurumu, dürtü kontrolünü, uykuyu ve stresle başa çıkmayı düzenler; SSRI'ların etki ettiği sistemin merkezi.","de":"The main source of serotonin to the forebrain: regulates mood, impulse control, sleep and coping with stress; the hub of the system SSRIs act on."},{"id":"pons","c":"#b98d68","p":null,"deep":true,"n":"Pons","ne":"Pons","s":"Köprü","g":"Beyin Sapı","ge":"Brainstem","d":"Korteks ile serebellum arasındaki köprü; noradrenalin (locus coeruleus) ve serotonin (rafe) kaynağı, REM uykusunun üreteci.","de":"The bridge between the cortex and the cerebellum; source of noradrenaline (locus coeruleus) and serotonin (raphe), and generator of REM sleep."},{"id":"lc","c":"#3a5fd9","p":null,"deep":true,"n":"Locus Coeruleus","ne":"Locus Coeruleus","s":"LC","g":"Beyin Sapı","ge":"Brainstem","d":"Beynin ana noradrenalin kaynağı: uyanıklığı, dikkati ve stres yanıtını ayarlar; küçük bir çekirdekten neredeyse tüm beyne yayılır.","de":"The brain’s main source of noradrenaline: tunes wakefulness, attention and the stress response; a small nucleus that reaches almost the whole brain."},{"id":"pbc","c":"#d63c78","p":null,"deep":true,"n":"Parabrakial Kompleks","ne":"Parabrachial Complex","s":"PBN","g":"Beyin Sapı","ge":"Brainstem","d":"Bedenden gelen tehlike sinyallerinin kavşağı: iç organ, tat, ağrı, ısı ve nefes darlığı bilgisini amigdala, hipotalamus ve insulaya aktarır.","de":"The crossroads for danger signals from the body: relays visceral, taste, pain, temperature and breathlessness information to the amygdala, hypothalamus and insula."},{"id":"medulla","c":"#a77b58","p":null,"deep":true,"n":"Medulla Oblongata","ne":"Medulla Oblongata","s":"MO","g":"Beyin Sapı","ge":"Brainstem","d":"Yaşamsal merkezler: solunum ritmi, kalp ve kan basıncı, yutma ve kusma; beyin ile omurilik arasındaki son geçit.","de":"Vital centers: breathing rhythm, heart and blood pressure, swallowing and vomiting; the last passage between the brain and the spinal cord."},{"id":"vagal","c":"#3fbfcf","p":null,"deep":true,"n":"Vagal Çekirdekler","ne":"Vagal Nuclei","s":"DMV / NA","g":"Beyin Sapı","ge":"Brainstem","d":"Medulladaki iki parasempatik çıkış: kalbi ve yüz-boğaz kaslarını düzenleyen nükleus ambiguus ile iç organları düzenleyen dorsal motor çekirdek.","de":"The two parasympathetic outputs in the medulla: the nucleus ambiguus, which regulates the heart and the muscles of the face and throat, and the dorsal motor nucleus…"},{"id":"cerebellum","c":"#5fb3a1","p":null,"deep":false,"n":"Serebellum (Beyincik)","ne":"Cerebellum","s":"CB","g":"Serebellum","ge":"Cerebellum","d":"Hareketi zamanlar ve düzeltir; aynı hesaplamayı düşünce, dil ve duyguya da uygular. Beyindeki nöronların çoğu buradadır.","de":"Times and corrects movement, and applies the same computation to thought, language and emotion. Most of the brain’s neurons are here."},{"id":"cb_ant","c":"#8bc34a","p":"cerebellum","deep":true,"n":"Ön Lob (Lobül I–V)","ne":"Anterior Lobe (Lobules I–V)","s":"I–V","g":"Serebellum","ge":"Cerebellum","d":"Serebellumun duyu-motor ön lobu: gövde ve uzuvların birinci somatotopik haritası; yürüme ve postürü düzenler.","de":"The sensorimotor anterior lobe of the cerebellum: the first somatotopic map of the trunk and limbs; regulates gait and posture."},{"id":"cb_vi","c":"#26a69a","p":"cerebellum","deep":true,"n":"Lobül VI","ne":"Lobule VI","s":"VI","g":"Serebellum","ge":"Cerebellum","d":"Duyu-motor ve bilişsel bölgeler arasındaki geçiş lobülü: hareket, dil ve dikkat görevlerinde etkinleşir.","de":"A transitional lobule between sensorimotor and cognitive regions: active in movement, language and attention tasks."},{"id":"cb_crus1","c":"#3f51b5","p":"cerebellum","deep":true,"n":"Crus I","ne":"Crus I","s":"Crus I","g":"Serebellum","ge":"Cerebellum","d":"Serebellumun bilişsel çekirdeği: prefrontal ve parietal kortekslerle döngü kurar, yürütücü işlevleri ve dili destekler.","de":"The cognitive core of the cerebellum: forms loops with prefrontal and parietal cortex and supports executive function and language."},{"id":"cb_crus2","c":"#8e24aa","p":"cerebellum","deep":true,"n":"Crus II","ne":"Crus II","s":"Crus II","g":"Serebellum","ge":"Cerebellum","d":"Sosyal ve bilişsel işlemeye katılan posterior lob bölgesi: zihinselleştirme ve yürütücü ağlarla bağlantılı.","de":"A posterior lobe region involved in social and cognitive processing: connected with mentalizing and executive networks."},{"id":"cb_viib","c":"#d81b60","p":"cerebellum","deep":true,"n":"Lobül VIIb","ne":"Lobule VIIb","s":"VIIb","g":"Serebellum","ge":"Cerebellum","d":"Crus II ile lobül VIII arasındaki, dikkat ve çalışma belleği ağlarıyla bağlantılı posterior lob lobülü.","de":"A posterior lobe lobule between Crus II and lobule VIII, connected with attention and working memory networks."},{"id":"cb_viii","c":"#fb8c00","p":"cerebellum","deep":true,"n":"Lobül VIII (VIIIa–VIIIb)","ne":"Lobule VIII (VIIIa–VIIIb)","s":"VIII","g":"Serebellum","ge":"Cerebellum","d":"İkinci duyu-motor vücut haritasını taşıyan lobül; dikkat ağlarıyla da bağlantılıdır.","de":"The lobule carrying the second sensorimotor body map; also connected with attention networks."},{"id":"cb_ix","c":"#6d4c41","p":"cerebellum","deep":true,"n":"Lobül IX (Tonsil)","ne":"Lobule IX (Tonsil)","s":"IX","g":"Serebellum","ge":"Cerebellum","d":"Varsayılan mod ağıyla bağlantılı posterior lob bölgesi; hemisferik kısmı serebellar tonsildir.","de":"A posterior lobe region connected with the default mode network; its hemispheric part is the cerebellar tonsil."},{"id":"cb_x","c":"#00acc1","p":"cerebellum","deep":true,"n":"Flokkulonodüler Lob (Lobül X)","ne":"Flocculonodular Lobe (Lobule X)","s":"X","g":"Serebellum","ge":"Cerebellum","d":"Vestibüloserebellum: dengeyi, göz–baş koordinasyonunu ve bakışın sabit tutulmasını düzenler.","de":"The vestibulocerebellum: regulates balance, eye–head coordination and holding gaze steady."},{"id":"cb_vermis","c":"#e53935","p":"cerebellum","deep":true,"n":"Posterior Vermis (Lobül VI–IX)","ne":"Posterior Vermis (Lobules VI–IX)","s":"Vermis","g":"Serebellum","ge":"Cerebellum","d":"Orta hattaki \"limbik serebellum\": duygu düzenleme, göz hareketleri ve otonom yanıtlarla ilişkili.","de":"The midline “limbic cerebellum”: linked to emotion regulation, eye movements and autonomic responses."},{"id":"cb_dentate","c":"#fdd835","p":"cerebellum","deep":true,"n":"Dentat Çekirdek","ne":"Dentate Nucleus","s":"DN","g":"Serebellum","ge":"Cerebellum","d":"Serebellumun en büyük derin çekirdeği: lateral hemisferlerin çıkışını talamus üzerinden motor ve prefrontal kortekse taşır.","de":"The largest deep cerebellar nucleus: carries the output of the lateral hemispheres via the thalamus to motor and prefrontal cortex."},{"id":"cb_interposed","c":"#f4511e","p":"cerebellum","deep":true,"n":"İnterpozit Çekirdek (Emboliform ve Globoz)","ne":"Interposed Nucleus (Emboliform and Globose)","s":"IP","g":"Serebellum","ge":"Cerebellum","d":"Paravermal bölgenin çıkışı: uzuv hareketlerini anlık olarak düzeltir; koşullu göz kırpma öğrenmesinde rol oynar.","de":"The output of the paravermal region: corrects limb movements on the fly; plays a role in conditioned eyeblink learning."}],"hafta":["dlpfc","ofc","mpfc","broca","premotor","motor","somato","spl","ipl","tpj","stg","itg","occipital","acc","insula","pcc","hippocampus","amygdala","bnst","nbm","dbb","caudate","putamen","gp","stn","sn","nacc","vp","thalamus","hypothalamus","hb","cc","midbrain","pag","vta","rn","rf","ppn","raphe","pons","lc","pbc","medulla","vagal","cerebellum"],"tanilar":[{"id":"dehb","c":"#e0862f","n":"Dikkat Eksikliği ve Hiperaktivite Bozukluğu","ne":"Attention-Deficit/Hyperactivity Disorder","s":"DEHB","se":"ADHD","d":"Dikkat, dürtü denetimi ve ödül devreleri; frontostriatal ve frontoparietal ağlar, dopamin ve noradrenalin.","de":"Attention, impulse control and reward circuits; frontostriatal and frontoparietal networks, dopamine and noradrenaline."},{"id":"osb","c":"#2fa8a0","n":"Otizm Spektrum Bozukluğu","ne":"Autism Spectrum Disorder","s":"OSB","se":"ASD","d":"Sosyal algı, zihin kuramı, duyusal işlemleme ve interosepsiyon devreleri; görüntüleme farkları küçük ve grup düzeyinde.","de":"Social perception, theory of mind, sensory processing and interoception circuits; imaging differences are small and group-level."},{"id":"okb","c":"#a867d6","n":"Obsesif Kompulsif Bozukluk","ne":"Obsessive-Compulsive Disorder","s":"OKB","se":"OCD","d":"Orbitofrontal korteks, singulat korteks, striatum ve talamustan geçen döngülerin \"takılıp kalması\".","de":"Loops through the orbitofrontal cortex, cingulate cortex, striatum and thalamus that \"get stuck\"."},{"id":"depresyon","c":"#5e82d9","n":"Depresyon","ne":"Depression","s":"Depresyon","se":"Depression","d":"Ödül, stres yanıtı ve duygu düzenleme devreleri; ergenlikte irritabilite ve anhedoni öne çıkabilir.","de":"Reward, stress response and emotion regulation circuits; irritability and anhedonia can come first in adolescence."},{"id":"yab","c":"#c99a2e","n":"Yaygın Anksiyete Bozukluğu","ne":"Generalized Anxiety Disorder","s":"YAB","se":"GAD","d":"Tehdit algısı (amigdala), belirsiz tehdide süreğen kaygı (BNST), beden duyumu (insula) ve prefrontal düzenleme.","de":"Threat perception (amygdala), sustained anxiety about uncertain threat (BNST), bodily sensation (insula) and prefrontal regulation."},{"id":"tssb","c":"#c4573f","n":"Travma Sonrası Stres Bozukluğu","ne":"Post-Traumatic Stress Disorder","s":"TSSB","se":"PTSD","d":"Korku öğrenmesi ve sönme devresi: amigdala aşırı, ventromedial PFC frenlemesi ve hipokampusun bağlam bilgisi zayıf.","de":"Fear learning and extinction circuit: an overactive amygdala, with weak ventromedial PFC braking and weak contextual input from the hippocampus."},{"id":"bipolar","c":"#d9608e","n":"Bipolar Bozukluk","ne":"Bipolar Disorder","s":"Bipolar","se":"Bipolar","d":"Duygu düzenleme (amigdala, ventrolateral PFC) ve ödül devreleri; mani ve depresif atak arasında dalgalanma.","de":"Emotion regulation (amygdala, ventrolateral PFC) and reward circuits; swings between mania and depressive episodes."},{"id":"sizofreni","c":"#4aa8c4","n":"Şizofreni","ne":"Schizophrenia","s":"Şizofreni","se":"Schizophrenia","d":"Striatumda artmış dopamin, hipokampus ve prefrontal korteks; olumlu, olumsuz ve bilişsel belirtiler.","de":"Increased striatal dopamine, the hippocampus and prefrontal cortex; positive, negative and cognitive symptoms."},{"id":"borderline","c":"#d0703f","n":"Borderline Kişilik Bozukluğu","ne":"Borderline Personality Disorder","s":"Borderline","se":"Borderline","d":"Duygu düzenleme devresi: olumsuz duygulara amigdala aşırı, DLPFC az yanıt; zihinselleştirme ve sosyal acı.","de":"Emotion regulation circuit: an overactive amygdala and an underactive DLPFC in response to negative emotion; mentalizing and social pain."},{"id":"tik","c":"#5fae55","n":"Tik Bozuklukları ve Tourette","ne":"Tic Disorders and Tourette Syndrome","s":"Tik","se":"Tics","d":"Duyusal-motor kortiko-striato-talamo-kortikal döngü; tikten önce gelen öncü dürtü insula ve ek motor alanla ilişkili.","de":"Sensorimotor cortico-striato-thalamo-cortical loop; the premonitory urge before tics is linked to the insula and supplementary motor area."}],"systems":[{"id":"SEEKING","slug":"seeking","c":"#f2b134","d":"merak, beklenti, coşkulu arayış","de":"curiosity, anticipation, eager seeking"},{"id":"RAGE","slug":"rage","c":"#e0483e","d":"öfke, engellenmişlik","de":"anger, frustration"},{"id":"FEAR","slug":"fear","c":"#8a7ff0","d":"korku, gerginlik, tetikte olma","de":"fear, tension, being on guard"},{"id":"LUST","slug":"lust","c":"#e05fa0","d":"cinsel arzu, erotik haz","de":"sexual desire, erotic pleasure"},{"id":"CARE","slug":"care","c":"#4fae7c","d":"şefkat, bakım verme isteği, sıcaklık","de":"tenderness, the urge to nurture, warmth"},{"id":"PANIC/GRIEF","slug":"panic-grief","c":"#4f86e0","d":"ayrılık acısı, yalnızlık, yas","de":"separation distress, loneliness, grief"},{"id":"PLAY","slug":"play","c":"#f08a5d","d":"neşe, oyunbazlık, kahkaha","de":"joy, playfulness, laughter"}],"nts":[{"id":"glu","c":"#4b8dff","n":"Glutamat Yolakları","ne":"Glutamate Pathways","s":"Glu","d":"Beynin ana uyarıcı sinyali: korteks, talamus ve hipokampusun projeksiyon nöronları kullanır; öğrenme ve belleğin taşıyıcısı, ketaminin hedefi.","de":"The brain’s main excitatory signal: used by the projection neurons of the cortex, thalamus and hippocampus."},{"id":"gaba","c":"#9b8cff","n":"GABA Yolakları","ne":"GABA Pathways","s":"GABA","d":"Beynin ana frenleyici sinyali: çoğu yerel ara nöronlardadır, uzun yolları bazal gangliyon, beyincik ve amigdala çıkışlarıdır.","de":"The brain’s main braking signal: mostly in local interneurons; its long pathways are the outputs of the basal ganglia, cerebellum and amygdala."},{"id":"da","c":"#f6c344","n":"Dopamin Yolakları","ne":"Dopamine Pathways","s":"DA","d":"Motivasyonun, öğrenmenin ve hareketin sinyali: dört ana yolla yayılır; stimülanlar ve antipsikotiklerin ortak hedefi.","de":"The signal of motivation, learning and movement: spreads along four main pathways; the shared target of stimulants and antipsychotics."},{"id":"5ht","c":"#3ad17a","n":"Serotonin Yolakları","ne":"Serotonin Pathways","s":"5-HT","d":"Rafe çekirdeklerinden bütün beyne yayılan düzenleyici: duygudurum, dürtü kontrolü, uyku ve ağrı; SSRI'ların hedefi.","de":"A modulator spreading from the raphe nuclei to the whole brain: mood, impulse control, sleep and pain; the target of SSRIs."},{"id":"ne","c":"#ff7a2f","n":"Noradrenalin Yolakları","ne":"Noradrenaline Pathways","s":"NE","d":"Locus coeruleus'tan yayılan uyanıklık ve dikkat sinyali; stres yanıtını başlatır, prefrontal işlevle ters-U ilişkisi vardır.","de":"A wakefulness and attention signal spreading from the locus coeruleus; it launches the stress response and has an inverted-U relationship with…"},{"id":"ach","c":"#22c7d6","n":"Asetilkolin Yolakları","ne":"Acetylcholine Pathways","s":"ACh","d":"Dikkat, öğrenme ve uyanıklığın kolinerjik sinyali: bazal önbeyinden kortekse, septumdan hipokampusa, beyin sapından talamusa.","de":"The cholinergic signal of attention, learning and wakefulness: from the basal forebrain to the cortex, from the septum to the hippocampus…"},{"id":"his","c":"#b8e04a","n":"Histamin Yolakları","ne":"Histamine Pathways","s":"HA","d":"Uyanıklığın kimyasal anahtarlarından: arka hipotalamustaki tuberomamiller çekirdekten bütün beyne.","de":"One of the chemical switches of wakefulness: from the tuberomammillary nucleus of the posterior hypothalamus to the whole brain."},{"id":"orx","c":"#d26cf0","n":"Oreksin (Hipokretin) Yolakları","ne":"Orexin (Hypocretin) Pathways","s":"OX","d":"Lateral hipotalamusun uyanıklık dengeleyicisi: öteki uyanıklık çekirdeklerini birlikte açık tutar; kaybı narkolepsiye yol açar.","de":"The wakefulness stabilizer of the lateral hypothalamus: keeps the other wakefulness nuclei on together; its loss causes narcolepsy."}],"nets":[{"id":"dmn","c":"#cd3e4e","n":"Default Mode Network","s":"DMN","t":"Varsayılan mod ağı","d":"Dış dünyadan çekilince etkinleşen ağ: kendini düşünme, anılar, geleceği tasarlama ve başkalarının zihnini anlama.","de":"The network that switches on when we withdraw from the outside world: thinking about oneself, memories, imagining the future and understanding other…"},{"id":"fpn","c":"#e69422","n":"Frontoparietal Control Network","s":"FPN","t":"Frontoparietal kontrol ağı","d":"Esnek bilişsel kontrolün merkezi: göreve göre öteki ağlarla bağlantısını değiştirip hedefe yönelik davranışı düzenler.","de":"The hub of flexible cognitive control: changes its connections with the other networks according to the task and regulates goal-directed behavior."},{"id":"md","c":"#2bbfd6","n":"Multiple-Demand (MD) Core","s":"MD","t":"Çoklu talep çekirdeği","d":"Zor olan hemen her görevde birlikte etkinleşen \"genel amaçlı\" çekirdek: akıcı zekâ ve problem çözmenin altyapısı.","de":"A “general-purpose” core that activates together in almost any difficult task: the infrastructure of fluid intelligence and problem solving."},{"id":"sal","c":"#c43afa","n":"Salience / Ventral Attention Network","s":"SN / VAN","t":"Belirginlik ve ventral dikkat ağı","d":"Önemli olanı fark eden ve dikkati oraya çeviren ağ: bedenden ve çevreden gelen belirgin sinyallere göre öteki ağlar arasında geçişi başlatır.","de":"The network that notices what matters and turns attention to it: initiates switching between the other networks according to salient signals from the…"},{"id":"dan","c":"#00760e","n":"Dorsal Attention Network","s":"DAN","t":"Dorsal dikkat ağı","d":"Amaca yönelik dikkati yöneten ağ: neye ve nereye bakılacağını yukarıdan aşağıya seçer, göz hareketlerini yönlendirir.","de":"The network that directs goal-driven attention: selects top-down what and where to look, and guides eye movements."},{"id":"smn","c":"#4682b4","n":"Somatomotor Network","s":"SMN","t":"Duyusal-motor ağ","d":"Bedeni hareket ettiren ve hisseden ağ; Yeo atlasında işitme korteksini de içerir. Doğumda en olgun ağlardandır.","de":"The network that moves and feels the body; in the Yeo atlas it also includes auditory cortex. One of the most mature networks at birth."},{"id":"vis","c":"#781286","n":"Visual Network","s":"VIS","t":"Görsel ağ","d":"Oksipital lobun görsel alanları: görüntünün çözümlenmesinden nesne ve hareket algısına uzanan ilk basamaklar.","de":"The visual areas of the occipital lobe: the first steps from analyzing the image to perceiving objects and motion."},{"id":"lim","c":"#b9d77a","n":"Limbic Network (Yeo)","s":"LIM","t":"Limbik ağ","d":"Yeo atlasında orbitofrontal korteks ve temporal kutuptan oluşan ağ; adı limbik olsa da amigdala ve hipokampusu içermez.","de":"In the Yeo atlas, a network made of the orbitofrontal cortex and temporal pole; despite its name, it does not include the amygdala or hippocampus."}],"ilaclar":[{"id":"fluoksetin","c":"#3ad17a","n":"Fluoksetin","ne":"Fluoxetine","g":"Antidepresanlar (SSRİ)","ge":"Antidepressants (SSRIs)","s":"SSRİ","se":"SSRI","d":"Çocuk-ergen depresyonu ağ meta-analizinde plasebodan anlamlı üstün bulunan tek antidepresan (2016); çok uzun yarı ömrü ve güçlü CYP2D6 ketlemesi nedeniyle etkileşimde…","de":"The only antidepressant significantly better than placebo in a network meta-analysis of child and adolescent depression (2016)."},{"id":"sertralin","c":"#3ad17a","n":"Sertralin","ne":"Sertraline","g":"Antidepresanlar (SSRİ)","ge":"Antidepressants (SSRIs)","s":"SSRİ","se":"SSRI","d":"Çocuk OKB'sinde (POTS, 2004) ve anksiyetesinde (CAMS, 2008) büyük çalışmaları olan SSRİ; bu çalışmalarda en iyi sonuç BDT ile birlikte alındı.","de":"An SSRI with large trials in pediatric OCD (POTS, 2004) and anxiety (CAMS, 2008); in these trials the best results came from combining it with CBT."},{"id":"essitalopram","c":"#3ad17a","n":"Essitalopram","ne":"Escitalopram","g":"Antidepresanlar (SSRİ)","ge":"Antidepressants (SSRIs)","s":"SSRİ","se":"SSRI","d":"Sitalopramın etkin yarısı; ABD'de ergen depresyonunda ve çocuk-ergen yaygın anksiyetesinde onaylı, AB ürün bilgisinde ve bakılan Türk KÜB'lerinde 18 yaş altı için…","de":"The active enantiomer of citalopram; approved in the US for adolescent depression and for generalized anxiety in children and adolescents."},{"id":"klomipramin","c":"#3ad17a","n":"Klomipramin","ne":"Clomipramine","g":"Antidepresanlar (trisiklik)","ge":"Antidepressants (tricyclic)","s":"Trisiklik antidepresan","se":"Tricyclic antidepressant","d":"Serotonin geri alımını güçlü ketleyen trisiklik antidepresan; noradrenalin geri alımını kendisi ve etkin metaboliti desmetilklomipramin ketler.","de":"A tricyclic antidepressant that strongly inhibits serotonin reuptake; noradrenaline reuptake is inhibited by the drug and its active metabolite desmethylclomipramine."},{"id":"risperidon","c":"#e0a03a","n":"Risperidon","ne":"Risperidone","g":"Antipsikotikler","ge":"Antipsychotics","s":"İkinci kuşak antipsikotik","se":"Second-generation antipsychotic","d":"Otizmde irritabilite için ilk büyük çok merkezli çalışma (RUPP, 2002) bu ilaçla; güçlü D2 ve çok güçlü 5-HT2A blokajı.","de":"The first large multicenter trial for irritability in autism (RUPP, 2002) used this drug; strong D2 and very strong 5-HT2A blockade."},{"id":"aripiprazol","c":"#e0a03a","n":"Aripiprazol","ne":"Aripiprazole","g":"Antipsikotikler","ge":"Antipsychotics","s":"D2 kısmi agonisti","se":"D2 partial agonist","d":"D2'yi neredeyse tamamen doldurur ama tam kapatmaz: prolaktini genellikle yükseltmez, metabolik yükü sınıfta düşük olanlardan; akatizi akılda tutulur.","de":"Occupies nearly all D2 receptors without fully blocking them: usually does not raise prolactin, among the lower metabolic burdens in its class; keep akathisia in mind."},{"id":"olanzapin","c":"#e0a03a","n":"Olanzapin","ne":"Olanzapine","g":"Antipsikotikler","ge":"Antipsychotics","s":"İkinci kuşak antipsikotik","se":"Second-generation antipsychotic","d":"Ergen şizofrenisi ve bipolar manisinde etkili bulundu; çocuk ve ergen karşılaştırmalarında kilo ve metabolik yükü en yüksek bulunanlardan…","de":"Found effective in adolescent schizophrenia and bipolar mania; among the highest weight and metabolic burdens in pediatric comparisons…"},{"id":"ketiapin","c":"#e0a03a","n":"Ketiapin","ne":"Quetiapine","g":"Antipsikotikler","ge":"Antipsychotics","s":"İkinci kuşak antipsikotik","se":"Second-generation antipsychotic","d":"D2'ye gevşek bağlanıp hızla ayrıldığı düşünülür (hızlı ayrışma hipotezi): ekstrapiramidal etki ve prolaktin artışı az.","de":"Thought to bind D2 loosely and let go quickly (fast-dissociation hypothesis): few extrapyramidal effects and little prolactin rise."},{"id":"klozapin","c":"#e0a03a","n":"Klozapin","ne":"Clozapine","g":"Antipsikotikler","ge":"Antipsychotics","s":"İkinci kuşak antipsikotik","se":"Second-generation antipsychotic","d":"Tedaviye dirençli şizofrenide başvurulan ilaç; D2 doluluğu düşük, 5-HT2 doluluğu yüksek. Agranülositoz ve miyokardit riski nedeniyle yakın izlem ister.","de":"Used in treatment-resistant schizophrenia; low D2 occupancy and high 5-HT2 occupancy. The risks of agranulocytosis and myocarditis call for close monitoring."},{"id":"metilfenidat","c":"#ff7a2f","n":"Metilfenidat","ne":"Methylphenidate","g":"DEHB ilaçları","ge":"ADHD medications","s":"Uyarıcı","se":"Stimulant","d":"Dopamin ve noradrenalin taşıyıcılarını kapatır; ağ meta-analizine göre çocuk ve ergen DEHB'sinde tercih edilen ilk ilaç (2018). Etkisi saatler içinde başlar.","de":"Blocks the dopamine and noradrenaline transporters; the preferred first-choice medication for children and adolescents with ADHD in a network meta-analysis (2018)."},{"id":"atomoksetin","c":"#ff7a2f","n":"Atomoksetin","ne":"Atomoxetine","g":"DEHB ilaçları","ge":"ADHD medications","s":"Seçici noradrenalin geri alım inhibitörü","se":"Selective noradrenaline reuptake inhibitor","d":"Yalnız NET'i kapatır: prefrontal kortekste noradrenalini ve dopamini artırır, striatum ve akumbenste dopamini değiştirmez (hayvan verisi).","de":"Blocks only NET: raises noradrenaline and dopamine in the prefrontal cortex and leaves dopamine unchanged in the striatum and accumbens (animal data)."},{"id":"lityum","c":"#6ab0d9","n":"Lityum","ne":"Lithium","g":"Duygudurum düzenleyiciler","ge":"Mood stabilizers","s":"Lityum tuzu","se":"Lithium salt","d":"Bipolar bozuklukta kullanılır; 7–17 yaşta manide plasebodan üstün bulundu. Güvenlik aralığı dar olduğu için kan düzeyi izlemi gerekir.","de":"Used in bipolar disorder; found superior to placebo for mania at ages 7–17. Its narrow safety margin calls for blood level monitoring."},{"id":"guanfasin","c":"#ff7a2f","n":"Guanfasin","ne":"Guanfacine","g":"DEHB ilaçları","ge":"ADHD medications","s":"α2A agonisti (uzun salımlı)","se":"α2A agonist (extended release)","d":"Taşıyıcıya değil reseptöre etki eder: prefrontal piramidal nöronların dikenlerindeki α2A reseptörlerini uyararak çalışma belleği ağını güçlendirdiği düşünülür…","de":"Acts on a receptor, not a transporter: by stimulating α2A receptors on the dendritic spines of prefrontal pyramidal neurons, it is thought to strengthen the…"}]};
